import json, os, base64, shutil, urllib.error
from discord_assets import get_assets, add_asset, delete_asset

with open('games.json') as games_file:  
    game_data = json.load(games_file)
    if len(game_data) == 0:
        print('no games saved')
        exit(1)

    # sort all the supported games title ids from the games.json file 
    supported_games_title_ids = set(n['titleId'].lower() for n in game_data['ps4'])

    print('found %d supported games in games.json' % len(supported_games_title_ids))

    discord_assets = get_assets()
    discord_asset_names = set(n['name'] for n in discord_assets if n['name'] != 'ps4_main') # dont remove the main icon
    print('found %d discord assets' % len(discord_assets))
    if len(discord_assets) > 0:
        # games that have a discord asset that are no longer supported by this repo
        removed_games = [ i for i in discord_asset_names if i not in supported_games_title_ids ]
        if len(removed_games) > 0:
            print('removing %d games' % len(removed_games))
            for game in removed_games:
                asset_id = next(i for i in discord_assets if i['name'] == game)['id']
                try:
                    delete_asset(asset_id)
                    print('deleted %s' % asset_id)
                except:
                    print('failed deleting %s' % asset_id)
        else:
            print('no games need to be removed')
    else:
        print('no discord assets found so none were removed')

    # games that are now supported that don't exist in the discord application
    added_games = [ i for i in supported_games_title_ids if i not in discord_asset_names ]
    if len(added_games) > 0:
        print('adding %d games...' % len(added_games))
        for game in added_games:
            with open(f'ps4/{game}.png', "rb") as image_file:
                try:
                    encoded_string = base64.b64encode(image_file.read())
                    add_asset(game, 'data:image/png;base64,%s' % encoded_string.decode("utf-8"))
                    print('added %s' % game)
                except HTTPError:
                    print('request failed while trying to add %s' % game)
    else:
        print('no new games added')

# Soluzione proposta esame "Dinosauri"

FILE_NAME = 'mazzo.txt'
NUM_CARTE = 30

# punteggi dei diversi dinosauri. Uso un dizionario come mappa "colore"-->punteggio
PUNTEGGI = {
    'Rosso': 5,
    'Giallo': 3,
    'Verde': 1
}


def leggi_mazzo(file_name):
    try:
        infile = open(file_name, 'r')
    except IOError:
        exit('Impossibile aprire il file')

    mazzo = []
    for dino in infile:
        dino = dino.strip()
        if dino not in PUNTEGGI:
            print(f'Carta {dino} non valida (viene ignorata)')
        else:
            mazzo.append(dino)
    infile.close()

    if len(mazzo) != NUM_CARTE:
        print(f'Il numero di carte {len(mazzo)} non corrisponde a {NUM_CARTE}')
        return []

    return mazzo


def distribuisci_carte(mazzo):
    carte1 = []
    carte2 = []
    for i in range(0, len(mazzo), 2):
        carte1.append(mazzo[i])
        carte2.append(mazzo[i + 1])
    return (carte1, carte2)


def partita(carte1, carte2):
    punti1 = punti2 = 0
    tavolo = 0
    while len(carte1) > 0 and len(carte2) > 0:
        c1 = carte1.pop(0)
        c2 = carte2.pop(0)
        print(f'Giocatore 1: {c1} -- Giocatore 2: {c2}')
        tavolo = tavolo + PUNTEGGI[c1] + PUNTEGGI[c2]
        if c1 == c2:
            print('Pareggio')
        elif PUNTEGGI[c1] > PUNTEGGI[c2]:
            print('Vince Giocatore 1')
            punti1 = punti1 + tavolo
            tavolo = 0
        else:
            print('Vince Giocatore 2')
            punti2 = punti2 + tavolo
            tavolo = 0
        print(f'Punteggio: {punti1} -- {punti2}')
    return (punti1, punti2)


def main():
    mazzo = leggi_mazzo(FILE_NAME)
    (carte1, carte2) = distribuisci_carte(mazzo)
    (punti1, punti2) = partita(carte1, carte2)
    if punti1 > punti2:
        print(f'Ha vinto il Giocatore 1 con {punti1} punti')
    elif punti2 > punti1:
        print(f'Ha vinto il Giocatore 2 con {punti2} punti')
    else:
        print(f'I giocatori hanno pareggiato con {punti1} punti ciascuno')


main()

import functools
import json
import sys
from statistics import mean

from parser_utils import Parser, NoQuestionFound, AAID_REGEX, FIND_DIGIT_REGEX


class InvalidURLException(BaseException):
    def __init__(self, url, *args):
        self.__url = url
        super().__init__(*args)

    def __str__(self):
        return f"Invalid URL {self.__url}"


def catch(func):
    @functools.wraps(func)
    def stub(self, *args, **kwargs):
        try:
            return func(self, *args, *kwargs)
        except NoQuestionFound:  # raised in parser, questions finished
            return True, True
        except KeyboardInterrupt:
            sys.exit()  # quits script
        except BaseException as e:
            return None, e

    return stub


class AnswerHandler:
    """
    handles all the answer logic
    """

    def __init__(self, session):
        self.sesh = session
        self.headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)'
                                      ' Chrome/71.0.3578.98 Safari/537.36'}
        self.process_ans_url = 'https://www.drfrostmaths.com/homework/process-answer.php'
        self.answer_functions = {'expression': self.answer_expression,
                                 'numeric': self.answer_numeric,
                                 'eqnsolutions': self.answer_eqnsolutions,
                                 'coordinate': self.answer_coordinate,
                                 'multiplechoice': self.answer_multiplechoice,
                                 'textual': self.answer_textual,
                                 'fraction': self.answer_fraction,
                                 'vector': self.answer_vector,
                                 'table': self.answer_table,
                                 'shape': self.answer_shape,
                                 'list': self.answer_list,
                                 'standardform': self.answer_standardform}

    @catch
    def answer_questions(self, url: str):
        """
        main loop answers questions util an error is raised
        due to no more questions, invalid input or connection errors.

        Decorator handles returns.

        Answer process:

        - Post deliberately wrong answer without aaid i.e. {'qid': 1228, 'qnum': 1, 'expression-answer-1': 1}.
        - Sever sends correct answer without registering an attempt as no aaid was associated with the request.
        - Parse response for answer, use appropriate function.
        - Send answer with aaid i.e. {'qid': 1228, 'qnum': 1, 'expression-answer-1': "parsed answer", aaid: 12848}.
        - question answered!

        repeat.
        """

        try:
            aaid = FIND_DIGIT_REGEX.findall(AAID_REGEX.findall(url)[0])[0]
        except IndexError:
            raise InvalidURLException(url)

        while True:  # main loop
            # remove &qnum=NUMBER in case already appended
            page = self.sesh.get("".join(url.split("&qnum=")[:1]), headers=self.headers).text  # get question page
            data, type_ = Parser.parse(page)  # parse question data
            answer = self.find_answer(data, type_)  # retrieve answer to question
            data['aaid'] = aaid
            try:
                result = self.answer_functions[type_](data, answer)  # select appropriate function to process answer
            except KeyError:
                self.new_type(answer, type_)  # not implemented type
                continue  # skips auto submit

            self.submit(result)

    def find_answer(self, data: dict, type_: str):
        """
        Attempts to find the correct answer to the current question.

        :param data: request payload
        :param type_: answer type
        :return: correct answer string
        """
        data = dict(data)
        data[f'{type_}-answer-1'] = '1'  # prepare incorrect  answer
        print(f'Question number: {data["qnum"]}', '|', f'Question type: {type_}')
        r = self.sesh.post(self.process_ans_url, data=data, headers=self.headers)  # submit incorrect answer
        _json = json.loads(r.text)
        return _json['answer']  # parse correct answer

    def submit(self, data: dict):
        # noinspection PyBroadException
        try:
            r = self.sesh.post(self.process_ans_url, data=data, timeout=3)
        except BaseException:
            return False

        _json = json.loads(r.text)
        if not _json['isCorrect']:
            self.wrong_answer(_json, data)
            return False
        return True

    @staticmethod
    def new_type(answer: dict, type_: str):
        print(f'No system in place to auto submit this answer type ({type_}) yet you will have to type it in manually:'
              f'\n {answer}')
        input('Press enter to proceed: ')

    @staticmethod
    def wrong_answer(response, data: dict):
        print('-- The wrong answer was submitted --')
        print('The following data if for debugging:')
        print(f'Request: {data}')
        print(f'Response: {response}')

    # answer specific functions --:

    @staticmethod
    def answer_expression(data, answer):
        answer = [answer['main']]
        data['expression-answer'] = answer
        return data

    @staticmethod
    def answer_numeric(data, answer):
        for index, item in enumerate(answer):
            if item['exact']:
                data[f'numeric-answer-{index + 1}'] = item['exact']
            else:
                # find mid value
                data[f'numeric-answer-{index + 1}'] = mean([float(item["to"]), float(item["from"])])
        return data

    @staticmethod
    def answer_eqnsolutions(data, answer):
        data['eqnsolutions-answer'] = str(answer).replace("'", '"').replace(' ', '')
        return data

    @staticmethod
    def answer_coordinate(data, answer):
        data['expression-answer-x'] = answer['x']
        data['expression-answer-y'] = answer['y']
        return data

    @staticmethod
    def answer_multiplechoice(data, answer):
        data['multiplechoice-answer[]'] = answer
        return data

    @staticmethod
    def answer_textual(data, answer):
        for index, item in enumerate(answer):
            data[f'textual-answer-{index + 1}'] = item
        return data

    @staticmethod
    def answer_fraction(data, answer):
        data['fraction-numer'] = answer['numer']
        data['fraction-denom'] = answer['denom']
        return data

    @staticmethod
    def answer_vector(data, answer):
        data['expression-answer-vector'] = str(answer).replace("'", '"')
        return data

    @staticmethod
    def answer_table(data, answer):
        for z, i in enumerate(answer):
            for p, x in enumerate(i):
                if x:
                    data[f'table-answer-{z + 1}-{p + 1}'] = x
        data['expression-answer-table'] = str(answer).replace("'", '"')
        return data

    @staticmethod
    def answer_shape(data, answer):
        data['shape-answer'] = str(answer).replace("'", '"').replace(' ', '')
        return data

    @staticmethod
    def answer_list(data, answer):
        ans = ','.join(answer)
        data['list-answer'] = ans
        return data

    @staticmethod
    def answer_standardform(data, answer):
        data['expression-answer-main'] = answer['main']
        data['expression-answer-power'] = answer['power']
        return data

#!/usr/bin/python
# -*- coding: UTF-8 -*-
import re
import time
from datetime import timedelta, timezone, datetime
from random import randint
from re import Pattern

from requests import session, Response, Session

from notifier import Notifier

shanghai_tz = timezone(timedelta(hours=8), name='Asia/Shanghai')


def get_current_hour() -> int:
    now = datetime.utcnow().replace(tzinfo=timezone.utc)
    return now.astimezone(shanghai_tz).hour


class Job:
    _login_header: dict = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Host': 'pass.neu.edu.cn',
        'Origin': 'https://pass.neu.edu.cn',
    }

    _init_url: str = 'https://e-report.neu.edu.cn/login'

    _service_url: str = 'https://e-report.neu.edu.cn/notes/create'

    _update_info_url: str = 'https://e-report.neu.edu.cn/api/notes'

    _feedback_url: str = "https://e-report.neu.edu.cn/notes"

    _lt_matcher: Pattern = re.compile(r'name="lt" value="(.+?)"')

    _login_path_matcher: Pattern = re.compile(r'id="loginForm" action="(.+?)"')

    _token_matcher: Pattern = re.compile(r'name="_token" value="(.+?)"')

    _name_matcher: Pattern = re.compile(r'当前用户：(.+?) <span')

    _class_matcher: Pattern = re.compile(r'"suoshubanji":"(.+?)"')

    _date_matcher: Pattern = re.compile(r'"created_on":"(.+?)"')

    _wrong_auth: str = '账号或密码错误'
    _bad_info: str = '信息获取失败'
    _bad_init_login: str = '获取登陆信息失败'

    def __init__(self, username: str, password: str, ip: str = ''):
        self._username: str = username
        self._password: str = password
        self._ip: str = ip
        self._client: Session = session()

        # 获取到的跨步骤共用中间信息
        self._token: str = ""
        self._name: str = ""
        self._lt = ""
        self._login_path: str = ""
        self._class: str = ""
        self._date: str = ""

    @property
    def _login_body(self) -> str:
        return f'rsa={self._username}{self._password}{self._lt}&ul={len(self._username)}&pl={len(self._password)}&lt={self._lt}&execution=e1s1&_eventId=submit'

    @property
    def _login_url(self) -> str:
        return f'https://pass.neu.edu.cn{self._login_path}'

    @property
    def _update_info_body(self) -> str:
        return f'_token={self._token}&jibenxinxi_shifoubenrenshangbao=1&profile%5Bxuegonghao%5D={self._username}&profile%5Bsuoshubanji%5D={self._class}&jiankangxinxi_muqianshentizhuangkuang=%E6%AD%A3%E5%B8%B8&xingchengxinxi_weizhishifouyoubianhua=0&qitashixiang_qitaxuyaoshuomingdeshixiang='

    @property
    def _update_info_header(self) -> dict:
        h = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Host': 'e-report.neu.edu.cn',
            'Origin': 'https://e-report.neu.edu.cn',
        }
        if len(self._ip) > 0:
            h['X-Forwarded-For'] = self._ip
        return h

    @property
    def _info_url(self) -> str:
        return f'https://e-report.neu.edu.cn/api/profiles/{self._username}?xingming={self._name}'

    @property
    def _body_temperature(self) -> float:
        return 36 + randint(4, 7) / 10

    @property
    def _report_body_temperature_url(self) -> str:
        hour = get_current_hour()
        item_id = 1 if 7 <= hour <= 9 else 2 if 12 <= hour <= 14 else 3
        return f'https://e-report.neu.edu.cn/inspection/items/{item_id}/records'

    @property
    def _report_body_temperature_body(self) -> str:
        return f'_token={self._token}&temperature={self._body_temperature}&suspicious_respiratory_symptoms=0&symptom_descriptions='

    @staticmethod
    def _is_login_success(resp: Response) -> bool:
        return resp.url.startswith("https://e-report.neu.edu.cn")

    # property 不好看
    def _is_reported(self) -> bool:
        return self._date == time.strftime(r'%Y-%m-%d', time.localtime())

    @staticmethod
    def _unexpected_exception(error: Exception = None) -> str:
        return f'网络错误或其他错误\n{error}'

    def _login(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._init_url)
            lt: list = self._lt_matcher.findall(resp.text)
            lp: list = self._login_path_matcher.findall(resp.text)
            if len(lt) < 1 or len(lp) < 1:
                return False, self._bad_init_login
            self._lt = lt[0]
            self._login_path = lp[0]

            resp: Response = self._client.post(self._login_url, data=self._login_body, headers=self._login_header)
            if self._is_login_success(resp):
                return True, ''
            return False, self._wrong_auth
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _login_service(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._service_url)
            self._token = self._token_matcher.findall(resp.text)[0]
            self._name = self._name_matcher.findall(resp.text)[0]
            return True, ''
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _get_info(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._info_url)

            if resp.text.find(self._username) == -1:
                return False, self._bad_info

            date = self._date_matcher.findall(resp.text)
            klass = self._class_matcher.findall(resp.text)

            if len(date) < 1 or len(klass) < 1:
                return False, self._bad_info

            self._date = date[0]
            self._class = klass[0]

            return True, ''
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _update_info(self) -> (bool, str):
        try:
            resp: Response = self._client.post(self._update_info_url, data=self._update_info_body,
                                               headers=self._update_info_header)
            if resp.status_code == 201:
                return True, ""
            return False, resp.text
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _report_body_temperature(self):
        try:
            resp: Response = self._client.post(self._report_body_temperature_url,
                                               data=self._report_body_temperature_body,
                                               headers=self._update_info_header)
            print(resp.status_code)
            if resp.status_code == 200:
                return True, ""
            return False, resp.text
        except Exception as e:
            return False, self._unexpected_exception(e)

    def do(self, notifier: Notifier):
        today = time.strftime('%m/%d/%Y')

        # 登陆
        success, msg = self._login()
        if not success:
            notifier.send(f"{today} 登陆失败", msg)
            return
        # 进入平台
        success, msg = self._login_service()
        if not success:
            notifier.send(f"{today} 鉴权失败", msg)
            return
        # 获取信息
        success, msg = self._get_info()
        if not success:
            notifier.send(f"{today} 获取已有信息失败", msg)
            return
        # 是否今日有签到过
        if not self._is_reported():
            # 打卡
            success, msg = self._update_info()
            if not success:
                notifier.send(f"{today} 打卡失败", msg)
                return
            notifier.send(f"{today} 打卡成功", "I'm fine, thank you.")

        # 上报体温
        success, msg = self._report_body_temperature()
        if not success:
            notifier.send(f"{today} 上报体温失败", msg)
            return
        notifier.send(f"{today} 上报体温成功", "I'm fine, really thank you.")

#!/usr/bin/env python3
import os
import sys
import re
import subprocess
import qrcode
import colorama

import constants

def get_platform() -> str:
    """
    Returns the name of the platform where the application is currently running
    """
    platforms = {
        'linux': constants.LINUX,
        'linux1': constants.LINUX,
        'linux2': constants.LINUX,
        'darwin': constants.MAC,
        'win32': constants.WINDOWS
    }

    if not sys.platform in platforms:
        return sys.platform

    return platforms[sys.platform]

def get_profiles() -> list:
    """
    Gets a list of names from saved wifi networks in the current platform
    """
    profiles = []

    platform = get_platform()

    try:
        if platform == constants.MAC:
            # Command found here : https://coderwall.com/p/ghl-cg/list-known-wlans
            profiles = run_command(f"defaults read ~/Library/Logs/com.apple.wifi.syncable-networks.plist | grep \" SSID\" | sed 's/^.*= \(.*\);$/\\1/' | sed 's/^\"\\(.*\)\"$/\\1/'").split('\n')
        elif platform == constants.LINUX:
            if os.getuid() != 0:
                ssid = run_command(f"sudo ls /etc/NetworkManager/system-connections/ | grep .nmconnection").split('\n')
            else:
                ssid = run_command(f"ls /etc/NetworkManager/system-connections/ | grep .nmconnection").split('\n')

            for entry in ssid:
                profiles.append(entry.split('.nmconnection')[0])
        elif platform == constants.WINDOWS:
            # Reference: https://www.geeksforgeeks.org/getting-saved-wifi-passwords-using-python/
            # getting meta data
            meta_data = run_command('netsh wlan show profiles | findstr ":"')

            if meta_data != "":
                # splitting data line by line
                data = meta_data.split('\n')

                if len(data) > 0:
                    # skip the first element in data since it does not contain a valid profile returned by netsh command
                    profiles = [d.split(':')[1].strip(' .\r') for d in data[1:]]
    except Exception as ex:
        print(f'Error: {ex}')

    return profiles

def generate_wifi_dict(profiles: list) -> dict:
    """
    Generates a dictionary with the wifi name as key and the password as it's value
    """
    wifi_dict = {}

    if profiles is None:
        print(f'List is not defined.')
        return

    if len(profiles) == 0:
        print(f'List is empty.')
        return

    for ssid in profiles:
        if get_platform() == constants.MAC and len(profiles) > 1:
            password = "*****"
        else:
            password = get_password(ssid)

        wifi_dict[ssid] = password

    return wifi_dict

def get_password(ssid: str) -> str:
    """
    Gets the password for a given SSID
    """
    password = ""

    if ssid == "" or ssid is None:
        print("SSID is not defined")
        return password

    platform = get_platform()

    try:
        if platform == constants.MAC:
            password = run_command(f"security find-generic-password -l \"{ssid}\" -D 'AirPort network password' -w")
        elif platform == constants.LINUX:
            # Check if the user is running with super user privilages
            if os.getuid() != 0:
                password = run_command(f"sudo nmcli -s -g 802-11-wireless-security.psk connection show '{ssid}'")
            else:
                password = run_command(f"nmcli -s -g 802-11-wireless-security.psk connection show '{ssid}'")
        elif platform == constants.WINDOWS:
            password = run_command(f"chcp 437 | netsh wlan show profile name=\"{ssid}\" key=clear | findstr Key")

            if password != "":
                password = re.findall(r"Key Content\s+:\s(.*)", password)

                if len(password) > 0:
                    password = password[0]
                else:
                    password = ""
    except Exception as ex:
        print(f'Error: {ex}')

    return password

def run_command(command: str) -> str:
    """
    Runs a given command using subprocess module
    """
    if command == "" or command is None:
        return ""

    env = os.environ.copy()
    env["LANG"] = "C"
    output, _ = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, shell=True, env=env).communicate()
    return output.decode("utf-8", errors="replace").rstrip("\r\n")

def print_dict(ssid: dict) -> None:
    """
    Prints the contents of the given dictionary that contains the wifi name and password
    """
    if ssid is None:
        print(f'Dictionary is not defined.')
        return

    if len(ssid) == 0:
        print(f'Dictionary is empty.')
        return

    print("----------------------------------------------")
    print("{:<30}| {:<}".format("SSID", "Password"))
    print("----------------------------------------------")

    for key, value in ssid.items():
        print("{:<30}| {:<}".format(key, value))

    print("----------------------------------------------")
    # If macOS and list 

    if get_platform() == constants.MAC and len(ssid) > 1:
        print(f"Use 'wifi-password -s <SSID>' to find a specific WIFI password")

