import os
import sys
import subprocess

project_path = os.path.join(os.path.dirname(__file__), 'vibora')

# Seeking for files pending compilation.
pending_compilation = set()
for root, dirs, files in os.walk(project_path):
    for file in files:
        if file.endswith('.pyx'):
            pending_compilation.add(os.path.join(root, file))
        elif file.endswith('.py'):
            if (file[:-3] + '.pxd') in files:
                pending_compilation.add(os.path.join(root, file))
        elif file.endswith(('.so', '.c', '.html')):
            os.remove(os.path.join(root, file))

# Calling Cython to compile our extensions.
cython = os.path.join(os.path.dirname(sys.executable), 'cython')
process = subprocess.run([cython] + list(pending_compilation) + ['--fast-fail'])
if process.returncode != 0:
    raise SystemExit(f'Failed to compile .pyx files to C.')

# Building native extensions.
process = subprocess.run(
    [
        sys.executable,
        os.path.join(os.path.dirname(project_path), 'setup.py'),
        'build_ext',
        '--inplace'
    ]
)
if process.returncode != 0:
    raise SystemExit(f'Failed to build native modules.')

print('Build process completed successfully.')

from utils.helpers import cached, cleanup_mul_1, opcode, to_exp2

from .algebra import mul_op, sub_op


def type_to_mask(s):
    lookup = {
        "bool": 1,
        "uint8": 8,
        "uint16": 16,
        "uint32": 32,
        "uint64": 64,
        "int8": 8,
        "bytes1": 1,
        "int16": 16,
        "bytes2": 16,
        "int32": 32,
        "bytes4": 32,
        "int64": 64,
        "bytes8": 64,
        "int128": 128,
        "uint128": 128,
        "bytes16": 128,
        "addr": 160,
        "address": 160,
        "uint256": 256,
        "bytes32": 256,
        "int256": 256,
        "int": 256,
        "uint": 256,
    }

    if s in lookup:
        return lookup[s]
    else:
        return None


def mask_to_type(num, force=False):
    # force causes to always return some soft of type,
    # if it's not found in the lookup then the smallest
    # one that fits

    lookup = {
        1: "bool",
        8: "uint8",
        16: "uint16",
        32: "uint32",
        64: "uint64",
        128: "uint128",
        160: "addr",
        256: "uint256",
    }

    if type(num) != int:
        return num

    if num in lookup:
        return lookup[num]

    elif force:
        if num > 256:
            return "big" + str(num)

        for mask, res in lookup.items():
            if mask > num:
                return lookup[mask]

        assert False

    else:
        return None


def get_bit(num, pos):
    return 1 if num & 2 ** pos > 0 else 0


def mask_to_int(size, offset):
    assert type(size) in (int, float), size
    assert type(offset) in (int, float), offset

    return (2 ** size - 1) * (2 ** offset)


def find_mask(num):
    # finds a mask that encompasses the number

    assert type(num) == int

    i = 0
    while get_bit(num, i) == 0 and i < 256:
        i += 1
    mask_pos = i - i % 8

    mask_pos_plus_len = 256

    while i < 256:
        if get_bit(num, i) != 0:
            mask_pos_plus_len = i - i % 8 + 8
        i += 1

    return (mask_pos_plus_len - mask_pos, mask_pos)


assert find_mask(0xFABBA10000) == (24, 16)
assert find_mask(0xFABBA10000) == (24, 16)
assert find_mask(0x7ABBA20000) == (24, 16)  # rounding to eights


@cached
def to_mask(num):
    num = cleanup_mul_1(num)

    if opcode(num) == "not":
        return to_neg_mask(num[1])

    if opcode(num) == "sub":
        if opcode(num[1]) == "exp" and num[2] == 1:
            mul = to_exp2(num[1][1])
            if mul == None:
                return None

            mask_pos = 0
            mask_len = mul_op(mul, num[1][2])

            # add type assert, that num[1][2] < 32?

            return (mask_len, sub_op(256, mask_len))

    if opcode(num) == "add" and num[1] == -1:
        return to_mask(("sub", num[2], 1,))

    if type(num) != int:
        return None

    i = 0
    while get_bit(num, i) == 0 and i < 256:
        i += 1
    mask_pos = i

    while get_bit(num, i) == 1 and i < 256:
        i += 1
    mask_pos_plus_len = i

    while i < 256:
        if get_bit(num, i) != 0:
            return None
        i += 1

    return mask_pos_plus_len - mask_pos, mask_pos


def to_neg_mask(num):
    if opcode(num) == "not":
        return to_mask(num[1])

    if type(num) != int:
        return None

    i = 0
    while get_bit(num, i) == 1 and i < 256:
        i += 1
    mask_pos = i

    while get_bit(num, i) == 0 and i < 256:
        i += 1
    mask_pos_plus_len = i

    while i < 256:
        if get_bit(num, i) != 1:
            return None
        i += 1

    return mask_pos_plus_len - mask_pos, mask_pos

import numpy as np

class kFoldGenerator():
    '''
    Data Generator
    '''
    k = -1      # the fold number
    x_list = [] # x list with length=k
    y_list = [] # x list with length=k

    # Initializate
    def __init__(self, k, x, y):
        if len(x)!=k or len(y)!=k:
            assert False,'Data generator: Length of x or y is not equal to k.'
        self.k=k
        self.x_list=x
        self.y_list=y

    # Get i-th fold
    def getFold(self, i):
        isFirst=True
        for p in range(self.k): 
            if p!=i:
                if isFirst:
                    train_data       = self.x_list[p]
                    train_targets    = self.y_list[p]
                    isFirst = False
                else:
                    train_data      = np.concatenate((train_data, self.x_list[p]))
                    train_targets   = np.concatenate((train_targets, self.y_list[p]))
            else:
                val_data    = self.x_list[p]
                val_targets = self.y_list[p]
        return train_data,train_targets,val_data,val_targets

    # Get all data x
    def getX(self):
        All_X = self.x_list[0]
        for i in range(1,self.k):
            All_X = np.append(All_X,self.x_list[i], axis=0)
        return All_X

    # Get all label y
    def getY(self):
        All_Y = self.y_list[0]
        for i in range(1,self.k):
            All_Y = np.append(All_Y,self.y_list[i], axis=0)
        return All_Y

    # Get all label y
    def getY_one_hot(self):
        All_Y = self.getY()
        return np.argmax(All_Y, axis=1)

