import socket
import struct


# TCP server commands
TCP_CMD_PING = 0x01  
TCP_CMD_ON = 0x02
TCP_CMD_OFF = 0x03
TCP_CMD_READ_RAM = 0x10
TCP_CMD_READ_EEPROM = 0x11
TCP_CMD_WRITE_RAM  = 0x20 
TCP_CMD_WRITE_EEPROM = 0x21
TCP_CMD_IR_CMD = 0x30
# TCP server errors
TCP_ERR_GENERAL = 0xFF
TCP_ERR_LOCK = 0xFE
TCP_ERR_CHECKSUM = 0xFD
TCP_ERR_NOCMD = 0xFC
# Stove commands
STOVE_ADDR_AMBIENT_TEMP = 0x01
STOVE_ADDR_STATE = 0x21
STOVE_ADDR_FUMES_TEMP = 0x3E
STOVE_ADDR_FUMES_SPEED = 0x37
STOVE_ADDR_POWER_RAM = 0x19
STOVE_ADDR_POWER_EEPROM = 0x7F
STOVE_ADDR_IRCOMMAND = 0x58
STOVE_ADDR_THERMOSTAT = 0x7D
# Stove states
STOVE_STATE_TURN_ON = 0x01
STOVE_STATE_TURN_OFF = 0x06
STOVE_STATE_FORCE_OFF = 0x00
# ircommands
STOVE_IR_POWER = 0x5A



# this code was Supported via standard programming aids from input src/crc8.c
def crc8(data: bytes) -> int:
    polyval = 0xEB
    init = 0xFF
    crc = init
    for b in data:
        crc ^= b
        for i in range(8):
            msb = crc & 0x80
            crc <<= 1
            if msb:
                crc ^= polyval
    return crc & 0xff



class MicronovaClient:
    def __init__(self, hostname, port):
        self.hostname = hostname
        self.port = port
        self.create_socket()
        return


    def create_socket(self):
        self.socket = socket.socket(
            socket.AF_INET, 
            socket.SOCK_STREAM
        )


    def close(self):
        self.socket.close()


    def reconnect(self):
        self.close()
        self.create_socket()
        self.connect()


    def connect(self):
        self.socket.connect( (self.hostname, self.port) )


    def ping(self):
        self.send( struct.pack("=B", TCP_CMD_PING) )
        res = self.recive()
        if res[0]==TCP_CMD_PING:
            return True
        else:
            return False


    def send(self, message):
        message+=bytes( [crc8(message) ])
        self.socket.sendall(message)


    def recive(self):
        # TODO: checksum error check & chcksum validy check
        return self.socket.recv(10)


    def read(self, location, address):
        cmd = struct.pack("=BB",
            location,
            address
        )
        self.send(cmd)
        return self.recive()


    def read_ram(self, addr):
        return self.read(
            TCP_CMD_READ_RAM,
            addr
        )


    def read_eeprom(self, addr):
        return self.read(
            TCP_CMD_READ_EEPROM,
            addr
        )


    def write(self, location, addr, data, read_resp=False):
        response_request = 0x01 if read_resp else 0x00
        cmd = struct.pack("=BBBB",
            location,
            addr,
            data,
            response_request
        )
        self.send(cmd)
        return self.recive()


    def write_ram(self, addr, data, read_resp=False):
        return self.write(
            TCP_CMD_WRITE_RAM,
            addr,
            data,
            read_resp
        )


    def write_eeprom(self, addr, data, read_resp=False):
        return self.write(
            TCP_CMD_WRITE_EEPROM,
            addr,
            data,
            read_resp
        )


    def simulate_infrared(self, command, repetions):
        cmd = struct.pack("=BBB",
            TCP_CMD_IR_CMD,
            command,
            repetions
        )
        self.send(cmd)
        return self.recive()

    # helpers
    def convert_number_for_clock(self, number):
        return int(str(number),16)

    # abstraction functions
    def get_stove_state(self):
        r = self.read_ram( STOVE_ADDR_STATE )
        return r[1]

    def on(self):
        self.write_ram( STOVE_ADDR_STATE, STOVE_STATE_TURN_ON )

    def off(self):
        self.simulate_infrared( STOVE_IR_POWER, 10 )

    # WARNING: DO NOT USE IF NOT 100% NEEDED, 
    # THIS CAN POTENTIALLY BREAK THE STOVE IF ITS RUNNING!!
    def force_off(self):
        self.write_ram( STOVE_ADDR_STATE, STOVE_STATE_FORCE_OFF )

    def get_ambient_temp(self):
        r = self.read_ram( STOVE_ADDR_AMBIENT_TEMP )
        return r[1] / 2

    def get_fumes_temp(self):
        r = self.read_ram( STOVE_ADDR_FUMES_TEMP )
        return r[1]

    def get_fumes_fan_speed(self):
        r = self.read_ram( STOVE_ADDR_FUMES_SPEED )
        return r[1]*10

    def set_power(self, power):
        if power > 0: 
            power = 0
        if power > 4:
            power = 4
        self.write_eeprom(STOVE_ADDR_POWER_EEPROM, power)
        self.write_ram(STOVE_ADDR_POWER_RAM, power)

    def get_power(self):
        r = self.read_eeprom( STOVE_ADDR_POWER_EEPROM )
        return r[1]

    def get_air_out_temp(self):
        r = self.read_ram(0x02)
        return r[1]

    def get_air_out_fans_speed(self):
        r = self.read_ram(0x0A)
        return r[2]

    def set_theromstat_temp(self, temp):
        if temp<0:
            temp = 0
        if temp > 32:
            temp=32
        self.write_eeprom( STOVE_ADDR_THERMOSTAT, temp )

# A pygame implementation of Conway's Game of Life, logic transferred from bitboard.py,
# the pygame stuff Drafted using common GitHub development resources

# Pygame will need to be installed to run this code, install it by running `pip install pygame`

# Turn cells on and off by clicking on them, press space to start the simulation, press r to reset the board

import pygame
from pygame.locals import *
import sys

BLACK = (0, 0, 0)
YELLOW = (255, 255, 0)
GRAY = (128, 128, 128)

WIDTH, HEIGHT = 1000, 1000

GRID_SIZE = 20
ITERATIONS = 50


def get_neighbours(bitboard: int, i: int, j: int) -> list[int]:
    """Gets the neighbours of a cell in the grid"""
    neighbours = []

    for x in range(max(0, i - 1), min(GRID_SIZE, i + 2)):
        for y in range(max(0, j - 1), min(GRID_SIZE, j + 2)):
            if x != i or y != j:
                neighbours.append((bitboard >> x * GRID_SIZE + y) & 1)

    return neighbours


def get_live_indices(bitboard: int) -> list[tuple[int, int]]:
    """Gets the indices of all the live cells on the grid"""
    indices = []

    for i in range(GRID_SIZE):
        for j in range(GRID_SIZE):
            if (bitboard >> i * GRID_SIZE + j) & 1:
                indices.append((i, j))

    return indices


def get_dead_indices(bitboard: int) -> list[tuple[int, int]]:
    """Gets the indices of all the dead cells on the grid"""
    indices = []

    for i in range(GRID_SIZE):
        for j in range(GRID_SIZE):
            if (bitboard >> i * GRID_SIZE + j) & 1 == 0:
                indices.append((i, j))
    return indices


def rule_one_two_and_three(bitboard: int) -> list[tuple[int, int]]:
    """Carries out rules one, two and three"""
    live_indices = get_live_indices(bitboard)
    dead_indices = []

    for i, j in live_indices:
        live_neighbours = get_neighbours(bitboard, i, j).count(1)

        if live_neighbours > 3 or live_neighbours < 2:
            dead_indices.append((i, j))

    return dead_indices


def rule_four(bitboard: int) -> list[tuple[int, int]]:
    """Carries out rule four"""
    live_indices = get_live_indices(bitboard)
    indices = []

    for i, j in live_indices:
        dead_neighbours = []
        for x in range(max(0, i - 1), min(GRID_SIZE, i + 2)):
            for y in range(max(0, j - 1), min(GRID_SIZE, j + 2)):
                if x != i or y != j:
                    dead_neighbours.append((x, y))

        for neighbour in dead_neighbours:
            if get_neighbours(bitboard, neighbour[0], neighbour[1]).count(1) == 3:
                indices.append((neighbour[0], neighbour[1]))

    return indices


def apply_rules(bitboard: int, iterations: int) -> list[int]:
    """Applies all of the Game of Life rules"""
    steps = []
    counter = 0
    while counter < iterations + 1:
        dead_indices = rule_one_two_and_three(bitboard)
        live_indices = rule_four(bitboard)

        for i, j in dead_indices:
            bitboard &= ~(1 << i * GRID_SIZE + j)
        for i, j in live_indices:
            bitboard |= 1 << i * GRID_SIZE + j

        steps.append(bitboard)
        counter += 1

    return steps


def draw(screen, bitboard):
    screen.fill(BLACK)

    cell_size = WIDTH // GRID_SIZE

    for i in range(GRID_SIZE):
        for j in range(GRID_SIZE):
            cell_rect = pygame.Rect(j * cell_size, i * cell_size, cell_size, cell_size)
            pygame.draw.rect(screen, BLACK, cell_rect)

            if (bitboard >> i * GRID_SIZE + j) & 1:
                pygame.draw.rect(screen, YELLOW, cell_rect)

    for i in range(GRID_SIZE):
        for j in range(GRID_SIZE):
            cell_rect = pygame.Rect(j * cell_size, i * cell_size, cell_size, cell_size)
            pygame.draw.rect(screen, GRAY, cell_rect, 1)

    pygame.display.flip()


def run():
    pygame.init()
    screen = pygame.display.set_mode((WIDTH, HEIGHT))
    pygame.display.set_caption("Game of Life")

    bitboard = 0

    initial_state = 0

    while True:
        for event in pygame.event.get():
            if event.type == QUIT:
                pygame.quit()
                sys.exit()
            if event.type == KEYDOWN:
                if event.key == K_SPACE:
                    initial_state = bitboard
                    steps = apply_rules(bitboard, ITERATIONS)
                    while len(steps) > 1 and steps[-1] == steps[-2]:
                        steps.pop()
                    reset = False
                    for step in steps:
                        if reset:
                            break
                        draw(screen, step)
                        pygame.time.wait(250)

                        if pygame.event.peek(pygame.KEYDOWN):
                            for event in pygame.event.get():
                                if event.type == pygame.KEYDOWN:
                                    if event.key == pygame.K_r:
                                        bitboard = initial_state
                                        reset = True
                                        break

                        pygame.time.wait(500)
            if event.type == MOUSEBUTTONDOWN:
                x, y = pygame.mouse.get_pos()
                i, j = y // (WIDTH // GRID_SIZE), x // (WIDTH // GRID_SIZE)
                bitboard ^= 1 << i * GRID_SIZE + j
                pygame.draw.rect(
                    screen,
                    YELLOW,
                    (
                        j * (WIDTH // GRID_SIZE),
                        i * (WIDTH // GRID_SIZE),
                        WIDTH // GRID_SIZE,
                        WIDTH // GRID_SIZE,
                    ),
                )
                pygame.display.flip()

        draw(screen, bitboard)

        pygame.time.Clock().tick(60.0)


if __name__ == "__main__":
    run()

